public interface IEmbeddingClient{Task<float[]> EmbedAsync(string text,CancellationToken ct=default);}
public sealed class ResilientEmbeddingService(IEmbeddingClient client,IConfiguration config){public async Task<IReadOnlyList<EnterpriseDocumentIntelligence.BuildingBlocks.Messaging.EmbeddedChunk>> EmbedAsync(IReadOnlyList<EnterpriseDocumentIntelligence.BuildingBlocks.Messaging.ChunkContract> chunks,CancellationToken ct){if(chunks.Count==0)return [];var maxAttempts=Math.Clamp(config.GetValue<int?>("Embedding:MaxAttempts")??3,1,6);var delayMs=Math.Clamp(config.GetValue<int?>("Embedding:BaseDelayMs")??250,50,5000);var result=new List<EnterpriseDocumentIntelligence.BuildingBlocks.Messaging.EmbeddedChunk>(chunks.Count);foreach(var chunk in chunks){float[] vector=[];for(var attempt=1;attempt<=maxAttempts;attempt++){try{vector=await client.EmbedAsync(chunk.Text,ct);break;}catch when(attempt<maxAttempts){await Task.Delay(TimeSpan.FromMilliseconds(delayMs*Math.Pow(2,attempt-1)),ct);}}if(vector.Length==0)throw new InvalidOperationException($"Embedding failed for chunk {chunk.ChunkId}");result.Add(new(chunk.ChunkId,chunk.Number,chunk.Text,chunk.TokenCount,vector,chunk.Heading,chunk.PageNumber));}return result;}}
public sealed class AzureOpenAiEmbeddingClientAdapter(AzureOpenAiEmbeddingClient client):IEmbeddingClient{public Task<float[]> EmbedAsync(string text,CancellationToken ct=default)=>client.EmbedAsync(text,ct);}